def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70

    supply = day_context.get('supply', 0)
    day = day_context.get('day', 0)

    # Identify alive opponents
    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    # If no opponents alive, bid to secure water cheaply
    if not alive_opps:
        return max(0.0, min(my_status.get('budget', 0.0), DAILY_SALARY * 0.4))

    my_hp = my_status.get('hp', 0)
    my_budget = my_status.get('budget', 0.0)
    my_no_water_days = my_status.get('no_water_days', 0)

    # Read yesterday's bids from traces for immediate reaction
    prev_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(prev.get('bid'))

    # Estimate how aggressive the field was yesterday
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        avg_prev_bid = sum(prev_bids) / float(len(prev_bids))
    else:
        highest_prev_bid = 0.0
        avg_prev_bid = 0.0

    # Supply pressure: if supply is low, water is scarce -> bid higher.
    # Use thresholds aligned to scenario supply range [15,25].
    if supply <= 17.0:
        scarcity_factor = 0.95
    elif supply <= 20.0:
        scarcity_factor = 0.75
    else:
        scarcity_factor = 0.55

    # Our urgency based on HP and consecutive no-water days
    urgency = 0.0
    if my_hp <= 1:
        urgency = 1.0
    elif my_hp <= 2:
        urgency = 0.85
    elif my_hp <= 3:
        urgency = 0.65
    else:
        urgency = 0.45

    if my_no_water_days >= 2:
        urgency = min(1.0, urgency + 0.2)

    # Exploit: opponents likely overbid (yesterday averages > 110). We underbid unless we are in danger.
    # Target bid is a fraction of yesterday's highest bid, scaled by scarcity and urgency.
    # Keep cap to avoid mirroring their aggressive spending.
    if highest_prev_bid > 0:
        target = highest_prev_bid * (0.35 + 0.35 * urgency) * scarcity_factor
        # Also ensure we don't go too low when urgency is high
        floor = DAILY_SALARY * (0.25 + 0.45 * urgency) * scarcity_factor
        bid = max(floor, target)
    else:
        bid = DAILY_SALARY * (0.4 + 0.4 * urgency) * scarcity_factor

    # If our budget is low, bid more conservatively to preserve survival
    if my_budget <= DAILY_SALARY * 0.6:
        bid *= 0.7

    # Final clamp: cannot exceed budget
    bid = max(0.0, min(my_budget, bid))

    # If we are extremely low HP, ensure we bid enough to have a chance
    if my_hp <= 2 and my_budget > 0:
        bid = max(bid, min(my_budget, DAILY_SALARY * 0.85 * scarcity_factor))

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    prev_bids = []
    strong_prev = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('budget', 0) > 0:
                    strong_prev.append(float(bid))

    if not alive_opps:
        return float(min(budget, 20.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    live_high = max(strong_prev) if strong_prev else highest_prev

    pressure = 0
    if supply <= 16:
        pressure += 3
    elif supply <= 18:
        pressure += 2
    elif supply <= 21:
        pressure += 1

    if hp <= 3:
        pressure += 3
    elif hp <= 5:
        pressure += 2
    elif hp <= 7:
        pressure += 1

    if no_water >= 2:
        pressure += 3
    elif no_water >= 1:
        pressure += 1

    if day >= 8:
        pressure += 1

    affordable_safe = max(0.0, budget - 5.0)

    if pressure >= 6:
        target = max(82.0, live_high + 2.5)
    elif pressure >= 4:
        target = max(64.0, live_high + 1.5)
    elif pressure >= 2:
        target = max(42.0, live_high * 0.72)
    else:
        target = 24.0 if supply >= 22 else 32.0

    if live_high >= 140:
        if hp >= 6 and no_water == 0 and supply >= 19:
            target = min(target, 28.0)
        else:
            target = max(target, 88.0)
    elif live_high >= 120:
        if pressure <= 2 and supply >= 20:
            target = min(target, 30.0)
        else:
            target = max(target, 58.0)

    rich_opps = 0
    for opp in alive_opps:
        if opp.get('budget', 0) >= 100:
            rich_opps += 1
    if rich_opps == 0 and pressure <= 3:
        target *= 0.8

    target = min(target, affordable_safe)
    if hp <= 2 or no_water >= 2:
        target = min(budget, max(target, 85.0))

    if target < 0:
        target = 0.0
    return float(round(min(budget, target), 2))
